var $bm_rt;
var nullLayerNames = [
    'Wave-stroke: Path 1 [1.1.0]',
    'Wave-stroke: Path 1 [1.1.1]',
    'Wave-stroke: Path 1 [1.1.2]',
    'Wave-stroke: Path 1 [1.1.3]',
    'Wave-stroke: Path 1 [1.1.4]'
];
var origPath = thisProperty;
var origPoints = origPath.points();
var origInTang = origPath.inTangents();
var origOutTang = origPath.outTangents();
var getNullLayers = [];
function toShapeGroup(inputXY, shapeGroup) {
    const transformedXY = $bm_sub(inputXY, shapeGroup.transform.position);
    const scaledX = $bm_div(transformedXY[0], $bm_div(shapeGroup.transform.scale[0], 100));
    const scaledY = $bm_div(transformedXY[1], $bm_div(shapeGroup.transform.scale[1], 100));
    const angleRadians = $bm_neg(degreesToRadians(shapeGroup.transform.rotation));
    const rotatedX = $bm_sub($bm_mul(scaledX, Math.cos(angleRadians)), $bm_mul(scaledY, Math.sin(angleRadians)));
    const rotatedY = $bm_sum($bm_mul(scaledX, Math.sin(angleRadians)), $bm_mul(scaledY, Math.cos(angleRadians)));
    const newPosXY = $bm_sum([
        rotatedX,
        rotatedY
    ], shapeGroup.transform.anchorPoint);
    return newPosXY;
}
for (var i = 0, il = nullLayerNames.length; i < il; i++) {
    try {
        getNullLayers.push(effect(nullLayerNames[i])('ADBE Layer Control-0001'));
    } catch (err) {
        getNullLayers.push(null);
    }
}
for (var i = 0, il = getNullLayers.length; i < il; i++) {
    if (getNullLayers[i] != null && getNullLayers[i].index != thisLayer.index) {
        let targetValue = fromCompToSurface(getNullLayers[i].toComp(getNullLayers[i].anchorPoint));
        let containerGroup = thisProperty.propertyGroup(3);
        let limit = 40;
        const transformGroups = [];
        while (--limit && !(containerGroup instanceof Layer)) {
            if (containerGroup.transform && containerGroup.transform.position) {
                transformGroups.unshift(containerGroup);
            }
            containerGroup = containerGroup.propertyGroup(1);
        }
        transformGroups.forEach(g => targetValue = toShapeGroup(targetValue, g));
        origPoints[i] = targetValue;
    }
}
$bm_rt = createPath(origPoints, origInTang, origOutTang, origPath.isClosed());

